/// <summary>Self-contained Christmas clicker. The interface is built at runtime so the starter scene needs no manual wiring.</summary>
public class GingerbreadGame : MonoBehaviour
{
    [Serializable] public class Building { public string name, icon, description; public double baseCost, cps; public int owned; }
    [Serializable] public class Upgrade { public string name, icon, description; public double cost; public int kind; public bool bought; }
    [Serializable] class SaveData { public double cookies, earned, spent, clickPower, highestCps, playtime; public int clicks, golden, totalBuildings; public int[] buildings; public bool[] upgrades; public string achievements; public float music=0.5f, sfx=0.8f; public bool muted; }

    readonly Color pine = new Color(.055f,.22f,.17f), green = new Color(.13f,.39f,.28f), cream = new Color(1f,.96f,.85f), gold = new Color(1f,.72f,.23f), red = new Color(.68f,.16f,.16f), ink = new Color(.20f,.13f,.10f);
    readonly List<Building> buildings = new List<Building>(); readonly List<Upgrade> upgrades = new List<Upgrade>(); readonly HashSet<string> achievements = new HashSet<string>();
    double cookies, earned, spent, clickPower=1, highestCps; int clicks, golden, totalBuildings; float musicVolume=.5f,sfxVolume=.8f; bool muted;
    Canvas canvas; TMP_Text cookiesText,cpsText,clickText,feedback,bonusText,shopTitle; Button gingerButton; RectTransform shopContent; string tab="Bakery"; float saveTimer, goldenTimer=18f, prodBoostUntil, clickBoostUntil, playSeconds, textScale=1f; bool portraitLayout; AudioSource audioSource; GameObject resetDialog; Sprite circleSprite;

    void Awake(){ Application.targetFrameRate=60; Load(); SetupEconomy(); BuildUI(); StartCoroutine(ProductionLoop()); StartCoroutine(GoldenLoop()); }
    void OnApplicationPause(bool pause){if(pause)Save();} void OnApplicationFocus(bool focus){if(!focus)Save();} void OnApplicationQuit(){Save();}
    void Update(){saveTimer+=Time.unscaledDeltaTime;playSeconds+=Time.unscaledDeltaTime;if(saveTimer>=30f){Save();saveTimer=0;} RefreshHeader();}
    void SetupEconomy(){
        buildings.AddRange(new[]{
            new Building{name="Cursor",icon="CUR",description="A tiny festive helper clicks for you.",baseCost=15,cps=.1},
            new Building{name="Grandma",icon="GMA",description="Bakes warm gingerbread all day.",baseCost=100,cps=1},
            new Building{name="Christmas Farm",icon="FARM",description="Grows cinnamon, sugar and cheer.",baseCost=1100,cps=8},
            new Building{name="Bakery",icon="OVEN",description="The ovens never cool down.",baseCost=12000,cps=47},
            new Building{name="Factory",icon="FACT",description="Cookie production on a grand scale.",baseCost=130000,cps=260},
            new Building{name="Reindeer Workshop",icon="REIN",description="Powered by holiday magic.",baseCost=1400000,cps=1400},
            new Building{name="Christmas Tree Factory",icon="TREE",description="Premium cookies beneath every tree.",baseCost=20000000,cps=7800},
            new Building{name="Santa's Workshop",icon="SANTA",description="The North Pole's finest bakery.",baseCost=330000000,cps=44000}
        });
        upgrades.AddRange(new[]{
            U("Double Dough", "CLICK", "Double cookies per click.",50,0), U("Strong Gingerbread", "CLICK+", "Double cookies per click again.",500,0),
            U("Quick Cursor", "CUR", "Cursor production x2.",500,1), U("Grandma's Recipe", "GMA", "Grandma production x2.",2000,2),
            U("Fertile Farm", "FARM", "Farm production x2.",12000,3), U("Hotter Ovens", "OVEN", "Bakery production x2.",80000,4),
            U("Turbo Mixers", "FACT", "Factory production x2.",650000,5), U("Reindeer Magic", "REIN", "Reindeer production x2.",8000000,6),
            U("Holiday Spirit", "ALL", "All production x1.5.",100000,8), U("Golden Touch", "ALL+", "All production x2.",5000000,8)
        });
    }
    Upgrade U(string n,string i,string d,double c,int k)=>new Upgrade{name=n,icon=i,description=d,cost=c,kind=k};
    IEnumerator ProductionLoop(){while(true){yield return new WaitForSeconds(1);double gain=Cps();if(Time.time<prodBoostUntil)gain*=2;cookies+=gain;earned+=gain;CheckAchievements();}}
    IEnumerator GoldenLoop(){while(true){yield return new WaitForSeconds(1);goldenTimer-=1;if(goldenTimer<=0){goldenTimer=UnityEngine.Random.Range(24f,42f);ShowGolden();}}}
    double Cps(){double sum=0;for(int i=0;i<buildings.Count;i++){double mult=1;foreach(var u in upgrades)if(u.bought&&(u.kind==i+1||u.kind==8))mult*=u.kind==8?(u.name=="Holiday Spirit"?1.5:2):2;sum+=buildings[i].owned*buildings[i].cps*mult;}return sum;}

