        var top=Panel("Header",canvas.transform,new Vector2(0,1),new Vector2(1,1),new Vector2(0,1),new Vector2(0,portrait?-165:-105),pine);top.GetComponent<RectTransform>().sizeDelta=new Vector2(0,portrait?180:120);
        var title=Label(portrait?"GINGERBREAD CLICKER":"GINGERBREAD\nCLICKER",top.transform,portrait?22:26,cream,portrait?TextAlignmentOptions.Center:TextAlignmentOptions.Left);Place(title.rectTransform,portrait?new Vector2(.5f,1):new Vector2(0,1),portrait?new Vector2(.5f,1):new Vector2(0,1),portrait?new Vector2(0,-38):new Vector2(26,-58),portrait?new Vector2(700,58):new Vector2(250,76));title.fontStyle=FontStyles.Bold;
        cookiesText=Label("0 cookies",top.transform,30,cream,TextAlignmentOptions.Center);Place(cookiesText.rectTransform,new Vector2(.5f,1),new Vector2(.5f,1),new Vector2(0,portrait?-100:-44),new Vector2(470,portrait?66:48));cookiesText.fontStyle=FontStyles.Bold;
        cpsText=Label("0 per second",top.transform,17,new Color(.85f,.93f,.84f),TextAlignmentOptions.Center);Place(cpsText.rectTransform,new Vector2(.5f,1),new Vector2(.5f,1),new Vector2(0,portrait?-150:-82),new Vector2(400,portrait?50:28));
        MakeButton("SET",top.transform,new Vector2(1,1),new Vector2(portrait?-52:-42,portrait?-98:-55),new Vector2(portrait?90:74,portrait?60:48),gold,()=>SetTab("Settings"),15);
        var left=Panel("Play Area",canvas.transform,portrait?new Vector2(0,.38f):new Vector2(0,0),new Vector2(portrait?1:.62f,1),new Vector2(10,15),new Vector2(-10,portrait?-190:-130),new Color(.91f,.96f,.94f,.94f));
        var subtitle=Label("Make some holiday cookies!",left.transform,18,green,TextAlignmentOptions.Center);Place(subtitle.rectTransform,new Vector2(0,1),new Vector2(1,1),new Vector2(0,-24),new Vector2(-32,48));
        var cookie=MakeButton("",left.transform,new Vector2(.5f,.52f),new Vector2(0,5),new Vector2(280,280),new Color(1,1,1,.02f),ClickCookie,20);gingerButton=cookie.GetComponent<Button>();cookie.GetComponentInChildren<TMP_Text>().raycastTarget=false;cookie.GetComponent<Image>().color=new Color(1,1,1,.02f);DrawGingerbread(cookie.transform);
        var hint=Label("TAP THE GINGERBREAD!",left.transform,19,ink,TextAlignmentOptions.Center);Place(hint.rectTransform,new Vector2(.5f,.5f),new Vector2(.5f,.5f),new Vector2(0,-175),new Vector2(360,34));hint.fontStyle=FontStyles.Bold;
        clickText=Label("+1 per click",left.transform,20,red,TextAlignmentOptions.Center);Place(clickText.rectTransform,new Vector2(.5f,0),new Vector2(.5f,0),new Vector2(0,52),new Vector2(300,36));
        feedback=Label("",left.transform,23,gold,TextAlignmentOptions.Center);Place(feedback.rectTransform,new Vector2(.5f,.72f),new Vector2(.5f,.72f),Vector2.zero,new Vector2(520,60));
        bonusText=Label("",left.transform,16,green,TextAlignmentOptions.Center);Place(bonusText.rectTransform,new Vector2(.5f,0),new Vector2(.5f,0),new Vector2(0,20),new Vector2(400,25));
        var right=Panel("Shop",canvas.transform,portrait?new Vector2(0,0):new Vector2(.62f,0),portrait?new Vector2(1,.38f):new Vector2(1,1),portrait?new Vector2(10,10):new Vector2(5,15),new Vector2(-10,portrait?-10:-130),cream);
        var nav=Panel("Shop Navigation",right.transform,new Vector2(0,1),new Vector2(1,1),new Vector2(0,0),new Vector2(0,-62),pine);nav.GetComponent<RectTransform>().sizeDelta=new Vector2(0,62);
        MakeButton("BAKERY",nav.transform,new Vector2(0,1),new Vector2(portrait?110:60,-8),new Vector2(portrait?206:110,portrait?54:44),green,()=>SetTab("Bakery"),14);MakeButton("UPGRADES",nav.transform,new Vector2(0,1),new Vector2(portrait?360:175,-8),new Vector2(portrait?206:130,portrait?54:44),green,()=>SetTab("Upgrades"),14);MakeButton("MORE v",nav.transform,new Vector2(1,1),new Vector2(portrait?-110:-65,-8),new Vector2(portrait?170:115,portrait?54:44),green,()=>NextTab(),14);
        shopTitle=Label("THE BAKERY",right.transform,23,pine,TextAlignmentOptions.Center);Place(shopTitle.rectTransform,new Vector2(.5f,1),new Vector2(.5f,1),new Vector2(0,-83),new Vector2(380,36));
        var scrollObj=new GameObject("Shop Scroll",typeof(RectTransform),typeof(ScrollRect),typeof(Image),typeof(Mask));scrollObj.transform.SetParent(right.transform,false);var scrollRect=scrollObj.GetComponent<RectTransform>();scrollRect.anchorMin=new Vector2(0,0);scrollRect.anchorMax=new Vector2(1,1);scrollRect.offsetMin=new Vector2(10,10);scrollRect.offsetMax=new Vector2(-10,-120);scrollObj.GetComponent<Image>().color=new Color(1,1,1,.01f);scrollObj.GetComponent<Mask>().showMaskGraphic=false;var sr=scrollObj.GetComponent<ScrollRect>();
        var content=new GameObject("Content",typeof(RectTransform),typeof(VerticalLayoutGroup),typeof(ContentSizeFitter));content.transform.SetParent(scrollObj.transform,false);shopContent=content.GetComponent<RectTransform>();shopContent.anchorMin=new Vector2(0,1);shopContent.anchorMax=new Vector2(1,1);shopContent.pivot=new Vector2(.5f,1);shopContent.sizeDelta=new Vector2(0,0);var v=content.GetComponent<VerticalLayoutGroup>();v.spacing=8;v.padding=new RectOffset(2,2,4,8);v.childForceExpandHeight=false;v.childForceExpandWidth=true;content.GetComponent<ContentSizeFitter>().verticalFit=ContentSizeFitter.FitMode.PreferredSize;sr.content=shopContent;sr.horizontal=false;sr.vertical=true;
        SetTab("Bakery");RefreshHeader();
    }
    void SetTab(string t){tab=t;if(shopContent==null)return;foreach(Transform c in shopContent)Destroy(c.gameObject);shopTitle.text=t=="Bakery"?"THE BAKERY":t.ToUpperInvariant();if(t=="Bakery")for(int i=0;i<buildings.Count;i++)BuildBuildingCard(i);else if(t=="Upgrades")BuildUpgrades();else if(t=="Achievements")BuildAchievements();else if(t=="Statistics")BuildStats();else if(t=="Settings")BuildSettings();else BuildHelp();}
    void NextTab(){SetTab(tab=="Bakery"?"Upgrades":tab=="Upgrades"?"Achievements":tab=="Achievements"?"Statistics":tab=="Statistics"?"Settings":"Bakery");}
    void BuildBuildingCard(int i){var b=buildings[i];double price=b.baseCost*Math.Pow(1.15,b.owned);var card=Card($"[{b.icon}]  {b.name}   x{b.owned}",shopContent,portraitLayout?128:66);var txt=Label($"{b.description}\n{Short(b.cps)} cookies / sec each",card.transform,portraitLayout?15:13,ink,TextAlignmentOptions.Left);Place(txt.rectTransform,new Vector2(0,0),new Vector2(.68f,1),new Vector2(12,4),new Vector2(-8,portraitLayout?-62:-34));txt.textWrappingMode=TextWrappingModes.Normal;MakeButton(Short(price)+" cookies",card.transform,new Vector2(1,.5f),new Vector2(portraitLayout?-92:-68,0),new Vector2(portraitLayout?176:124,portraitLayout?60:42),cookies>=price?green:new Color(.55f,.59f,.54f),()=>BuyBuilding(i),portraitLayout?14:12);}
    void BuildUpgrades(){int count=0;foreach(var u in upgrades){if(u.bought)continue;bool unlocked=u.kind==0||u.kind==8||buildings[Mathf.Clamp(u.kind-1,0,7)].owned>0||earned>=u.cost*.25;if(!unlocked)continue;count++;var card=Card("["+u.icon+"]  "+u.name,shopContent,portraitLayout?128:82);var d=Label(u.description,card.transform,portraitLayout?15:13,ink,TextAlignmentOptions.Left);Place(d.rectTransform,new Vector2(0,0),new Vector2(.7f,1),new Vector2(12,4),new Vector2(-8,portraitLayout?-62:-34));d.textWrappingMode=TextWrappingModes.Normal;MakeButton(Short(u.cost)+" cookies",card.transform,new Vector2(1,.5f),new Vector2(portraitLayout?-92:-68,0),new Vector2(portraitLayout?176:124,portraitLayout?60:42),cookies>=u.cost?green:new Color(.55f,.59f,.54f),()=>BuyUpgrade(u),portraitLayout?14:12);}if(count==0)AddMessage("More recipes will unlock as your bakery grows!");}
    void BuildAchievements(){string[] names={"First Cookie","100 Cookies","1,000 Cookies","10,000 Cookies","First Grandma","First Bakery","100 Buildings","Millionaire Baker","Golden Gingerbread Collector","Christmas Master"};foreach(string n in names){bool done=achievements.Contains(n);var c=Card((done?"[DONE]  ":"[LOCKED]  ")+n,shopContent,portraitLayout?90:52);var t=Label(done?"Earned - nice work!":"Keep baking to unlock this achievement.",c.transform,13,ink,TextAlignmentOptions.Left);Place(t.rectTransform,new Vector2(0,0),new Vector2(1,1),new Vector2(12,0),new Vector2(-20,portraitLayout?-48:-27));}}
    void BuildStats(){AddMessage($"Total baked: {Short(earned)}\nCookies spent: {Short(spent)}\nTotal clicks: {clicks:N0}\nCookies per click: {Short(clickPower)}\nCurrent CPS: {Short(Cps())}\nHighest CPS: {Short(highestCps)}\nBuildings owned: {totalBuildings:N0}\nUpgrades: {CountUpgrades()}\nAchievements: {achievements.Count}\nPlay time: {TimeSpan.FromSeconds(playSeconds):hh\\:mm\\:ss}");}
    void BuildSettings(){AddMessage("SETTINGS\nNo sound files are included yet.\n\nSAVE PROGRESS stores your bakery on this computer.");var c=Card("SAVE PROGRESS",shopContent,68);MakeButton("SAVE",c.transform,new Vector2(1,.5f),new Vector2(-74,0),new Vector2(132,42),green,()=>{Save();Toast("Progress saved!");},portraitLayout?12:15);var r=Card("RESET GAME",shopContent,68);MakeButton("RESET",r.transform,new Vector2(1,.5f),new Vector2(-74,0),new Vector2(132,42),red,ConfirmReset,portraitLayout?12:15);AddMessage("Reset clears this game's saved progress.");}
    void BuildHelp(){AddMessage("HOW TO PLAY\nTap the big gingerbread to bake cookies. Buy helpers in the Bakery for automatic cookies. Upgrades improve clicking and production. Catch the Golden Gingerbread before it disappears for a surprise bonus. Your progress saves automatically every 30 seconds.");}
    void AddMessage(string s){var m=Label(s,shopContent,16,ink,TextAlignmentOptions.TopLeft);m.textWrappingMode=TextWrappingModes.Normal;m.rectTransform.sizeDelta=new Vector2(400,Mathf.Max(220,140+s.Split('\n').Length*27));}
    GameObject Card(string title,Transform parent,float h){var c=Panel(title,parent,new Vector2(0,1),new Vector2(1,1),Vector2.zero,Vector2.zero,new Color(1,1,1,.85f));var le=c.AddComponent<LayoutElement>();le.minHeight=h;le.preferredHeight=h;var t=Label(title,c.transform,portraitLayout?18:17,pine,TextAlignmentOptions.Left);Place(t.rectTransform,new Vector2(0,1),new Vector2(1,1),new Vector2(12,portraitLayout?-10:-8),new Vector2(-18,portraitLayout?48:25));t.fontStyle=FontStyles.Bold;return c;}
    void ClickCookie(){cookies+=clickPower*(Time.time<clickBoostUntil?5:1);earned+=clickPower;clicks++;CheckAchievements();if(gingerButton){var tr=gingerButton.transform;tr.localScale=Vector3.one*.94f;LeanRestore(tr);}Toast("+"+Short(clickPower)+" cookies!");}
    void LeanRestore(Transform t){StartCoroutine(RestoreScale(t));}IEnumerator RestoreScale(Transform t){yield return new WaitForSeconds(.06f);if(t)t.localScale=Vector3.one;}
    void BuyBuilding(int i){var b=buildings[i];double p=b.baseCost*Math.Pow(1.15,b.owned);if(cookies+1e-9<p)return;cookies-=p;spent+=p;b.owned++;totalBuildings++;if(b.owned==1)Unlock("First "+b.name);CheckAchievements();SetTab(tab);}
    void BuyUpgrade(Upgrade u){if(u.bought||cookies+1e-9<u.cost)return;cookies-=u.cost;spent+=u.cost;u.bought=true;if(u.kind==0)clickPower*=2;SetTab(tab);}
    void ShowGolden(){if(canvas==null)return;var g=MakeButton("GOLDEN\nCOOKIE",canvas.transform,new Vector2(.52f,.55f),new Vector2(0,0),new Vector2(150,115),gold,GoldenReward,18);g.name="Golden Gingerbread";StartCoroutine(RemoveGolden(g));}
    IEnumerator RemoveGolden(GameObject g){yield return new WaitForSeconds(12);if(g)Destroy(g);}
    void GoldenReward(){golden++;int r=UnityEngine.Random.Range(0,4);if(r==0){double n=Math.Max(25,earned*.08);cookies+=n;earned+=n;Toast("Golden bonus +"+Short(n)+" cookies!");}else if(r==1){prodBoostUntil=Time.time+30;Toast("2x production for 30 seconds!");}else if(r==2){clickBoostUntil=Time.time+30;Toast("5x clicks for 30 seconds!");}else{double n=Math.Max(100,Cps()*60);cookies+=n;earned+=n;Toast("A magical stash: +"+Short(n)+"!");}Unlock("Golden Gingerbread Collector");CheckAchievements();}
    void CheckAchievements(){if(earned>=1)Unlock("First Cookie");if(earned>=100)Unlock("100 Cookies");if(earned>=1000)Unlock("1,000 Cookies");if(earned>=10000)Unlock("10,000 Cookies");if(totalBuildings>=100)Unlock("100 Buildings");if(earned>=1000000)Unlock("Millionaire Baker");if(earned>=1000000000)Unlock("Christmas Master");highestCps=Math.Max(highestCps,Cps());}
    void Unlock(string n){if(achievements.Add(n))Toast("Achievement: "+n+"!");}
    void Toast(string s){if(feedback){feedback.text=s;StopCoroutine(nameof(ClearToast));StartCoroutine(ClearToast());}}IEnumerator ClearToast(){yield return new WaitForSeconds(2.3f);if(feedback)feedback.text="";}
    void RefreshHeader(){if(!cookiesText)return;cookiesText.text=Short(cookies)+" cookies";cpsText.text=Short(Cps())+" cookies / second";clickText.text=Short(clickPower*(Time.time<clickBoostUntil?5:1))+" per click";bonusText.text=Time.time<prodBoostUntil?"Double baking: "+Mathf.CeilToInt(prodBoostUntil-Time.time)+"s":Time.time<clickBoostUntil?"5x click power: "+Mathf.CeilToInt(clickBoostUntil-Time.time)+"s":"";}
    int CountUpgrades(){int n=0;foreach(var u in upgrades)if(u.bought)n++;return n;}
    string Short(double n){if(double.IsNaN(n)||double.IsInfinity(n))return "Lots";if(n>=1e12)return (n/1e12).ToString("0.##")+"T";if(n>=1e9)return (n/1e9).ToString("0.##")+"B";if(n>=1e6)return (n/1e6).ToString("0.##")+"M";if(n>=1e3)return (n/1e3).ToString("0.##")+"K";return Math.Floor(n).ToString("N0");}
    void Save(){try{var d=new SaveData{cookies=cookies,earned=earned,spent=spent,clickPower=clickPower,highestCps=highestCps,playtime=playSeconds,clicks=clicks,golden=golden,totalBuildings=totalBuildings,buildings=new int[buildings.Count],upgrades=new bool[upgrades.Count],achievements=string.Join("|",achievements),music=musicVolume,sfx=sfxVolume,muted=muted};for(int i=0;i<buildings.Count;i++)d.buildings[i]=buildings[i].owned;for(int i=0;i<upgrades.Count;i++)d.upgrades[i]=upgrades[i].bought;PlayerPrefs.SetString("GingerbreadSave",JsonUtility.ToJson(d));PlayerPrefs.Save();}catch(Exception e){Debug.LogWarning("Save failed: "+e.Message);}}
    void Load(){try{if(!PlayerPrefs.HasKey("GingerbreadSave"))return;var d=JsonUtility.FromJson<SaveData>(PlayerPrefs.GetString("GingerbreadSave"));if(d==null)return;cookies=Math.Max(0,d.cookies);earned=Math.Max(cookies,d.earned);spent=Math.Max(0,d.spent);clickPower=Math.Max(1,d.clickPower);highestCps=Math.Max(0,d.highestCps);clicks=Math.Max(0,d.clicks);golden=Math.Max(0,d.golden);totalBuildings=Math.Max(0,d.totalBuildings);musicVolume=d.music;sfxVolume=d.sfx;muted=d.muted;playSeconds=Mathf.Max(0,(float)d.playtime);pendingBuildings=d.buildings;pendingUpgrades=d.upgrades;if(!string.IsNullOrEmpty(d.achievements))foreach(var a in d.achievements.Split('|'))if(a.Length>0)achievements.Add(a);}catch(Exception e){Debug.LogWarning("Save data could not be loaded; starting fresh. "+e.Message);}}
    int[] pendingBuildings;bool[] pendingUpgrades;
    void Start(){if(pendingBuildings!=null)for(int i=0;i<Math.Min(buildings.Count,pendingBuildings.Length);i++)buildings[i].owned=Math.Max(0,pendingBuildings[i]);if(pendingUpgrades!=null)for(int i=0;i<Math.Min(upgrades.Count,pendingUpgrades.Length);i++)upgrades[i].bought=pendingUpgrades[i];totalBuildings=0;foreach(var b in buildings)totalBuildings+=b.owned;SetTab(tab);CheckAchievements();RefreshHeader();}
    void ConfirmReset(){if(resetDialog)return;resetDialog=Panel("Confirm Reset",canvas.transform,new Vector2(.5f,.5f),new Vector2(.5f,.5f),new Vector2(-210,-105),new Vector2(210,105),pine);Label("Reset all bakery progress?",resetDialog.transform,23,cream,TextAlignmentOptions.Center).rectTransform.SetInsetAndSizeFromParentEdge(RectTransform.Edge.Top,22,44);MakeButton("CANCEL",resetDialog.transform,new Vector2(.3f,0),new Vector2(0,42),new Vector2(110,42),green,()=>{Destroy(resetDialog);resetDialog=null;},16);MakeButton("RESET",resetDialog.transform,new Vector2(.7f,0),new Vector2(0,42),new Vector2(110,42),red,()=>{Destroy(resetDialog);resetDialog=null;ResetGame();},16);}
    void ResetGame(){PlayerPrefs.DeleteKey("GingerbreadSave");PlayerPrefs.Save();cookies=earned=spent=0;clickPower=1;highestCps=0;clicks=golden=totalBuildings=0;achievements.Clear();playSeconds=0;foreach(var b in buildings)b.owned=0;foreach(var u in upgrades)u.bought=false;SetTab("Bakery");Toast("Fresh start - happy baking!");}

    Sprite MakeCircleSprite(){const int n=96;var tex=new Texture2D(n,n,TextureFormat.RGBA32,false);tex.name="Runtime UI Circle";tex.wrapMode=TextureWrapMode.Clamp;tex.filterMode=FilterMode.Bilinear;for(int y=0;y<n;y++)for(int x=0;x<n;x++){float dx=(x+.5f-n*.5f)/(n*.5f),dy=(y+.5f-n*.5f)/(n*.5f);float d=Mathf.Sqrt(dx*dx+dy*dy);float a=Mathf.Clamp01((1f-d)*n*.5f);tex.SetPixel(x,y,new Color(1,1,1,a));}tex.Apply();return Sprite.Create(tex,new Rect(0,0,n,n),new Vector2(.5f,.5f),100);}
    Image CreateShape(Transform parent,Vector2 size,Vector2 pos,Color color,float rotation=0){var g=new GameObject("Decoration",typeof(RectTransform),typeof(Image));g.transform.SetParent(parent,false);var r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(.5f,.5f);r.anchoredPosition=pos;r.sizeDelta=size;r.localRotation=Quaternion.Euler(0,0,rotation);var img=g.GetComponent<Image>();img.sprite=circleSprite;img.color=color;img.raycastTarget=false;return img;}
    void DrawGingerbread(Transform parent){Color dough=new Color(.55f,.27f,.12f),icing=new Color(1f,.89f,.64f),dark=new Color(.19f,.10f,.07f),berry=new Color(.72f,.12f,.16f),mint=new Color(.12f,.48f,.30f);CreateShape(parent,new Vector2(105,48),new Vector2(-78,30),icing,27);CreateShape(parent,new Vector2(105,48),new Vector2(78,30),icing,-27);CreateShape(parent,new Vector2(87,32),new Vector2(-78,30),dough,27);CreateShape(parent,new Vector2(87,32),new Vector2(78,30),dough,-27);CreateShape(parent,new Vector2(60,111),new Vector2(-31,-77),icing);CreateShape(parent,new Vector2(60,111),new Vector2(31,-77),icing);CreateShape(parent,new Vector2(46,95),new Vector2(-31,-77),dough);CreateShape(parent,new Vector2(46,95),new Vector2(31,-77),dough);CreateShape(parent,new Vector2(130,164),new Vector2(0,3),icing);CreateShape(parent,new Vector2(116,150),new Vector2(0,3),dough);CreateShape(parent,new Vector2(122,122),new Vector2(0,96),icing);CreateShape(parent,new Vector2(108,108),new Vector2(0,96),dough);CreateShape(parent,new Vector2(10,10),new Vector2(-20,105),Color.white);CreateShape(parent,new Vector2(10,10),new Vector2(20,105),Color.white);CreateShape(parent,new Vector2(5,5),new Vector2(-20,105),dark);CreateShape(parent,new Vector2(5,5),new Vector2(20,105),dark);CreateShape(parent,new Vector2(28,7),new Vector2(0,78),icing);CreateShape(parent,new Vector2(14,14),new Vector2(0,42),berry);CreateShape(parent,new Vector2(14,14),new Vector2(0,7),mint);CreateShape(parent,new Vector2(14,14),new Vector2(0,-28),berry);}

    // small UI factory helpers
    TMP_Text Label(string s,Transform p,float size,Color col,TextAlignmentOptions align){var g=new GameObject("Text - "+s,typeof(RectTransform),typeof(TextMeshProUGUI));g.transform.SetParent(p,false);var t=g.GetComponent<TextMeshProUGUI>();t.text=s;t.font=TMP_Settings.defaultFontAsset;t.fontSize=size*textScale;t.fontWeight=FontWeight.Medium;t.color=col;t.alignment=align;t.enableAutoSizing=false;t.extraPadding=true;t.raycastTarget=false;return t;}
    GameObject Panel(string n,Transform p,Vector2 amin,Vector2 amax,Vector2 omin,Vector2 omax,Color col){var g=new GameObject(n,typeof(RectTransform),typeof(Image));g.transform.SetParent(p,false);var r=g.GetComponent<RectTransform>();r.anchorMin=amin;r.anchorMax=amax;r.offsetMin=omin;r.offsetMax=omax;g.GetComponent<Image>().color=col;return g;}
    GameObject MakeButton(string text,Transform p,Vector2 anchor,Vector2 pos,Vector2 size,Color col,UnityEngine.Events.UnityAction action,float fs){var g=Panel("Button - "+text,p,anchor,anchor,pos-size*.5f,pos+size*.5f,col);var b=g.AddComponent<Button>();var colors=b.colors;colors.normalColor=col;colors.highlightedColor=Color.Lerp(col,Color.white,.16f);colors.pressedColor=Color.Lerp(col,Color.black,.12f);colors.selectedColor=col;b.colors=colors;b.onClick.AddListener(action);var t=Label(text,g.transform,fs,Color.white,TextAlignmentOptions.Center);t.fontStyle=FontStyles.Bold;t.rectTransform.anchorMin=Vector2.zero;t.rectTransform.anchorMax=Vector2.one;t.rectTransform.offsetMin=new Vector2(4,2);t.rectTransform.offsetMax=new Vector2(-4,-2);return g;}
    void Place(RectTransform r,Vector2 amin,Vector2 amax,Vector2 pos,Vector2 size){r.anchorMin=amin;r.anchorMax=amax;r.anchoredPosition=pos;r.sizeDelta=size;}
